@Test
    public void acceptsLinesOrVects() {
        final Line<Double> any = new RandomLine<>();
        MatcherAssert.assertThat(
            new Perpendicular<>(
                any.direction(), new PerpLine<>(any).direction()
            ).resolve(new Decimal()),
            Matchers.is(true)
        );
    }

